class Solution {
public:
    int minConnectedGroups(vector<vector<int>>& intervals, int k) {
        sort(intervals.begin(), intervals.end());
        vector<vector<int>> merged;
        for (auto& iv : intervals) {
            if (!merged.empty() && iv[0] <= merged.back()[1])
                merged.back()[1] = max(merged.back()[1], iv[1]);
            else merged.push_back(iv);
        }
        int m = merged.size(), best = 0;
        long long cur = 0;
        for (int l = 0, r = 0; r < m - 1; r++) {
            cur += (long long)merged[r + 1][0] - merged[r][1];
            while (cur > k) cur -= (long long)merged[l + 1][0] - merged[l][1], l++;
            best = max(best, r - l + 1);
        }
        return m - best;
    }
};

