class Solution {
    public int minConnectedGroups(int[][] intervals, int k) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        List<long[]> merged = new ArrayList<>();
        for (int[] iv : intervals) {
            if (!merged.isEmpty() && iv[0] <= merged.get(merged.size() - 1)[1])
                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], iv[1]);
            else merged.add(new long[]{iv[0], iv[1]});
        }
        int m = merged.size(), best = 0, l = 0;
        long cur = 0;
        for (int r = 0; r < m - 1; r++) {
            cur += merged.get(r + 1)[0] - merged.get(r)[1];
            while (cur > k) { cur -= merged.get(l + 1)[0] - merged.get(l)[1]; l++; }
            best = Math.max(best, r - l + 1);
        }
        return m - best;
    }
}

