class Solution {
public:
    int minConnectedGroups(vector<vector<int>>& intervals, int k) {
        sort(intervals.begin(), intervals.end());
        vector<vector<int>> merged;
        for (auto& iv : intervals) {
            if (!merged.empty() && iv[0] <= merged.back()[1])
                merged.back()[1] = max(merged.back()[1], iv[1]);
            else merged.push_back(iv);
        }
        int m = merged.size();
        vector<long long> pref(m, 0);
        for (int i = 1; i < m; i++) pref[i] = pref[i - 1] + (long long)merged[i][0] - merged[i - 1][1];
        int best = 0;
        for (int r = 1; r < m; r++) {
            int lo = 0, hi = r - 1, l = r;
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                if (pref[r] - pref[mid] <= k) { l = mid; hi = mid - 1; }
                else lo = mid + 1;
            }
            best = max(best, r - l);
        }
        return m - best;
    }
};

